// normNum normalizes every numeric leaf to float64 so these structural
// comparisons do not depend on the int64/float64 distinction (number type
// mapping is asserted separately in TestParseNumber). Mirrors Python ==.
func normNum(v any) any {
	switch n := v.(type) {
	case *OrderedMap:
		m := make(map[string]any, n.Len())
		for _, k := range n.Keys() {
			m[k] = normNum(n.values[k])
		}
		return m
	case map[string]any:
		m := make(map[string]any, len(n))
		for k, val := range n {
			m[k] = normNum(val)
		}
		return m
	case []any:
		s := make([]any, len(n))
		for i, val := range n {
			s[i] = normNum(val)
		}
		return s
	case int:
		return float64(n)
	case int64:
		return float64(n)
	case uint64:
		return float64(n)
	case float64:
		return float64(n)
	default:
		return v
	}
}

